        // Add orphan step state (not in any run)
        state.record_step_result(
            "orphan",
            StepStatus::Success,
            std::time::Duration::ZERO,
            None,
        );

        // Add a run with a different step
        let record = super::super::RunRecord {
            timestamp: Utc::now(),
            workflow: "default".to_string(),
